list_shipping_classes.code:
final response = await client.shippingClasses
    .listShippingClasses(queryParams: {'limit': 20});
final shippingClasses = (response.map as Map)['shipping_classes'] as List;
for (final shippingClass in shippingClasses) {
  print('${(shippingClass as Map)['id']} ${shippingClass['name']}');
}
final pagination = (response.map as Map)['pagination'] as Map;
print(pagination['total']);

count_shipping_classes.code:
final response = await client.shippingClasses.countShippingClasses();
final shippingClasses = (response.map as Map)['shipping_classes'] as Map;
print(shippingClasses['count']);

create_shipping_class.code:
final response = await client.shippingClasses.createShippingClass({
  'shipping_class': {
    'name': 'Bulky Goods',
    'description': 'Items over 20kg',
  },
});
final shippingClass = (response.map as Map)['shipping_class'] as Map;
print(shippingClass['id']);

